      token: {}
run-name: ${{ github.events }}
jobs:
  a:
    runs-on: ubuntu-latest
    strategy:
      matrix:
        os: [a, b]
        v: "${{ fromJSON('[1]') }}"
    steps:
      - run: echo ${{ github.sha }} ${{ contains('a') }} ${{ format('{0} {1}', 1) }}
      - run: echo ${{ fromJSON('[1') }} ${{ secrets.token }} ${{ secrets.other }}
      - run: echo ${{ matrix.os }} ${{ matrix.arch }}
      - run: echo ${{ github.event.*[github.sha] }}
      - run: echo ${{ inputs.nothing }}
      - run: echo ${{ matrix.v }}
  caller:
    uses: owner/repo/.github/workflows/w.yml@v1
  after:
    needs: caller
    runs-on: ubuntu-latest
    steps:
      - run: echo ${{ needs.caller.outputs.anything }}

